function update(dt){game.elapsed+=dt;game.damageCooldown=Math.max(0,game.damageCooldown-dt);if(game.detonation>0){game.detonation=Math.max(0,game.detonation-dt);if(game.detonation<=0){showEnding(false);return;}}if(game.called&&game.hold>0){game.hold=Math.max(0,game.hold-dt);game.escapeElapsed+=dt;const cue=game.hold>45?60:game.hold>30?45:game.hold>15?30:game.hold>10?15:game.hold>5?10:game.hold>0?5:0;if(cue<game.lastLiftCue){game.lastLiftCue=cue;playTone(cue<=10?660:cue<=30?440:330,.18,'sine',cue<=10?.11:.065);if([30,10,5].includes(cue))showToast(tr(`AUFZUG IN ${cue} SEKUNDEN · BLEIB IN BEWEGUNG`,`ELEVATOR IN ${cue} SECONDS · KEEP MOVING`),1800);}if(game.hold===0){game.escapeElapsed=0;if(liftIndicator)liftIndicator.material=glowGreen;updateObjectives();showToast(tr('Türen entriegeln sich. Zurück zum Bedienfeld!','Doors unlocking. Get back to the control panel!'),4200);playTone(196,.7,'triangle',.16);}}else if(game.called&&game.hold<=0){game.escapeElapsed=Math.min(1,game.escapeElapsed+dt);const opening=clamp(game.escapeElapsed/1,0,1);for(const door of liftDoors){door.mesh.position.x=door.closedX+door.side*1.35*opening;if(door.collider)door.collider.x=door.mesh.position.x;if(opening>=.95&&door.collider)door.collider.disabled=true;}}if(!game.paused&&!game.playerDown){const forward=(keysDown.has('KeyW')||keysDown.has('ArrowUp')?1:0)-(keysDown.has('KeyS')||keysDown.has('ArrowDown')?1:0)-touchMove.y;const side=(keysDown.has('KeyD')||keysDown.has('ArrowRight')?1:0)-(keysDown.has('KeyA')||keysDown.has('ArrowLeft')?1:0)+touchMove.x;const moving=forward!==0||side!==0;const sprint=moving&&(touchSprint||keysDown.has('ShiftLeft')||keysDown.has('ShiftRight'))&&game.stamina>2;const speed=sprint?5.15:3.05;if(sprint)game.stamina=Math.max(0,game.stamina-24*dt);else game.stamina=Math.min(100,game.stamina+15*dt);const f=new THREE.Vector3(Math.sin(player.yaw),0,-Math.cos(player.yaw)),r=new THREE.Vector3(Math.cos(player.yaw),0,Math.sin(player.yaw));const v=f.multiplyScalar(forward).add(r.