function animate(now){const dt=Math.min(.5,Math.max(0,(now-lastTime)/1000||0));lastTime=now;for(const f of flickers){const wave=.88+.12*Math.sin(now*.0018+f.phase);f.light.intensity=f.base*wave*(Math.random()>.996?.12:1);}for(const p of particles){const a=p.points.geometry.attributes.position;for(let i=0;i<p.speeds.length;i++){a.array[i*3+1]+=(Math.sin(now*.0003+i)*.15)*dt;a.array[i*3+2]+=p.speeds[i]*dt;if(a.array[i*3+2]>18)a.array[i*3+2]=-82;}a.needsUpdate=true;}if(game.mode==='playing'&&!game.paused)update(dt);if(composer){composer.render();}else renderer.render(scene,camera);}

