function showToast(text,duration=2800){const el=$('#toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),duration);}
function ensureAudio(){if(!audioCtx){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return null;audioCtx=new AudioContext();masterGain=audioCtx.createGain();masterGain.gain.value=muted?0:Number($('#volume-slider')?.value??70)/100;masterGain.connect(audioCtx.destination);ambienceFilter=audioCtx.createBiquadFilter();ambienceFilter.type='lowpass';ambienceFilter.frequency.value=150;ambienceGain=audioCtx.createGain();ambienceGain.gain.value=0;ambienceFilter.connect(ambienceGain);ambienceGain.connect(masterGain);for(const [freq,level,type] of [[46,.026,'sine'],[51,.014,'triangle']]){const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.value=level;osc.connect(gain);gain.connect(ambienceFilter);osc.start();}audioCtx.addEventListener('statechange',()=>{if(audioCtx?.state==='suspended'&&!document.hidden)audioCtx.resume().catch(()=>{});});}if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});return audioCtx;}
function setAudioScene(active,threat=audioThreat){audioSceneActive=active;audioThreat=clamp(threat,0,1);const ctx=ensureAudio();if(!ctx||!ambienceGain)return;const now=ctx.currentTime;ambienceGain.gain.cancelScheduledValues(now);ambienceGain.gain.setTargetAtTime(active?.82+audioThreat*.32:0,now,.8);ambienceFilter.frequency.setTargetAtTime(150+audioThreat*380,now,1.2);}
function setMasterVolume(){const ctx=ensureAudio();if(!ctx||!masterGain)return;masterGain.gain.setTargetAtTime(muted?0:Number($('#volume-slider')?.value??70)/100,ctx.currentTime,.04);}
function playTone(freq=220,duration=.2,type='sine',volume=.1){if(muted)return;try{const ctx=ensureAudio();if(!ctx)return;const osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(.001,now+Math.max(.025,duration));osc.connect(gain);gain.connect(masterGain);osc.start(now);osc.stop(now+duration+.01);}catch(e){}}
function setScreen(id){$$('.screen').forEach(x=>x.classList.remove('visible'));if(id)$('#'+id)?.classList.add('visible');}
function updateObjectives(){const idx=game.called?(game.hold<=0?6:5):!game.storyDone?0:game.phase<=1?(game.keys===0?1:2):game.phase===2?3:game.power?5:4;$('#objective-text').textContent=objectives[game.lang][idx];$('#sector-name').textContent=tr(game.phase<2?'SEKTOR 01 · MEDIZIN':game.phase<3?'SEKTOR 02 · FORSCHUNG':'SEKTOR 03 · REAKTOR',game.phase<2?'SECTOR 01 · MEDICAL':game.phase<3?'SECTOR 02 · RESEARCH':'SECTOR 03 · REACTOR');$('#objective-progress').innerHTML=`KEYCARD ${String(game.keys).padStart(2,'0')} / 03 <span><i class="${game.keys>0?'filled':''}"></i><i class="${game.keys>1?'filled':''}"></i><i class="${game.keys>2?'filled':''}"></i></span>`;$('#log-list').innerHTML=objectives[game.lang].slice(0,6).map((s,i)=>`<li class="${i<game.phase?'complete':''}">${s}</li>`).join('');$('#squad-count').textContent=String(1+game.botCount).padStart(2,'0');const lift=interactables.find(i=>i.kind==='lift');if(lift)lift.label=game.called&&game.hold<=0?tr('Aufzug betreten','Board elevator'):tr('Oberflächenaufzug rufen','Call surface elevator');}
