function speakVoice(text,{rate=.94,pitch=.84,delay=0,caption=true}={}){if(caption)setSubtitle(`“${text}”`);if(!('speechSynthesis'in window)||!window.SpeechSynthesisUtterance)return;const serial=++speakVoice.serial;clearTimeout(speakVoice.timer);speakVoice.timer=setTimeout(()=>{if(serial!==speakVoice.serial)return;window.speechSynthesis.cancel();const line=new SpeechSynthesisUtterance(text);line.lang='en-US';line.rate=rate;line.pitch=pitch;line.volume=muted?0:.82;const voices=window.speechSynthesis.getVoices();line.voice=voices.find(v=>/^en-US/i.test(v.lang)&&/natural|enhanced/i.test(v.name))||voices.find(v=>/^en-US/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang))||null;window.speechSynthesis.speak(line);},delay);}
