const logText={de:['Wenn das die Sicherheit erreicht, ist der untere Flügel verloren. Das Ding im Beobachtungsraum reagiert auf Geräusche. Lauf nicht. Lass es nicht zu nah kommen.','Die Schlüsselkarten sind auf getrennte Sektoren verschlüsselt. Stelle den Hauptgenerator erst wieder her, wenn alle drei geborgen sind. Der Aufzug ist unser einziger Ausweg.'],en:['If this reaches security, the lower wing is gone. The thing in the observation room responds to sound. Do not run. Do not let it get close.','The keycards are encrypted to separate sectors. Restore the main generator only after all three are recovered. The lift is our only way out.']};
function setSubtitle(text){const e=$('#subtitles-line');if(!game.subtitleOn||!e)return;e.textContent=text;e.classList.add('show');clearTimeout(setSubtitle.timer);setSubtitle.timer=setTimeout(()=>e.classList.remove('show'),9000);}
function speakVoice(text,{rate=.94,pitch=.84,delay=0,caption=true}={}){if(caption)setSubtitle(`“${text}”`);if(!('speechSynthesis'in window)||!window.SpeechSynthesisUtterance)return;const serial=++speakVoice.serial;clearTimeout(speakVoice.timer);speakVoice.timer=setTimeout(()=>{if(serial!==speakVoice.serial)return;window.speechSynthesis.cancel();const line=new SpeechSynthesisUtterance(text);line.lang='en-US';line.rate=rate;line.pitch=pitch;line.volume=muted?0:.82;const voices=window.speechSynthesis.getVoices();line.voice=voices.find(v=>/^en-US/i.test(v.lang)&&/natural|enhanced/i.test(v.name))||voices.find(v=>/^en-US/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang))||null;window.speechSynthesis.speak(line);},delay);}
speakVoice.serial=0;
function playStoryLog(){game.storyDone=true;game.phase=Math.max(game.phase,1);speakVoice(logText.en[0],{rate:.87,pitch:.72});showToast(tr('KASSETTE · AUFZEICHNUNG 04:17','CASSETTE · RECORDING 04:17'),2200);setTimeout(()=>speakVoice(logText.en[1],{rate:.9,pitch:.76}),10000);playTone(90,.8,'sawtooth',.035);updateObjectives();}

